(()=>{'use strict';const pageRoot=document.querySelector('[data-directory]');if(!pageRoot)return;const category=pageRoot.dataset.directory,grid=document.querySelector('#catalog-grid'),count=document.querySelector('#directory-count'),pager=document.querySelector('#directory-pagination'),sort=document.querySelector('#directory-sort'),checks=[...document.querySelectorAll('[data-filter]')];const pageSize=12;let data=[],page=1,selected=[];try{const saved=JSON.parse(localStorage.getItem('elvaro-project')||'[]');if(Array.isArray(saved))selected=saved.filter(x=>typeof x==='string')}catch{}const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');const url=x=>'/products/details/'+encodeURIComponent(x.id)+'.html';function filtered(){let rows=data.filter(x=>category==='all'||x.cat===category);for(const key of ['application','installation','power','beam','ip']){const values=checks.filter(x=>x.dataset.filter===key&&x.checked).map(x=>x.value);if(values.length)rows=rows.filter(x=>Array.isArray(x[key])?x[key].some(v=>values.includes(v)):values.includes(x[key]))}if(sort.value==='az')rows.sort((a,b)=>a.name.localeCompare(b.name));if(sort.value==='za')rows.sort((a,b)=>b.name.localeCompare(a.name));return rows}function card(x){return '<article class="directory-card" data-id="'+escape(x.id)+'"><a class="directory-photo" href="'+url(x)+'"><img src="/assets/'+escape(x.image)+'" alt="'+escape(x.name)+'" width="600" height="600" loading="lazy"></a><h2><a href="'+url(x)+'">'+escape(x.name)+'</a></h2><p class="directory-meta">'+escape(x.meta)+'</p><div class="directory-card-actions"><button type="button" data-add="'+escape(x.id)+'" aria-pressed="'+selected.includes(x.id)+'">'+(selected.includes(x.id)?'Added ✓':'Add to Project')+'</button><a href="'+url(x)+'">View Details <span aria-hidden="true">→</span></a></div></article>'}function selection(){document.querySelector('#directory-selected').textContent=selected.length+' products selected'}function render(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(Math.max(1,page),pages);grid.innerHTML=rows.slice((page-1)*pageSize,page*pageSize).map(card).join('')||'<div class="directory-empty"><h2>'+(category==='landscape-lighting'?'Let’s find the right landscape lighting.':'No products match your selection.')+'</h2><p>'+(category==='landscape-lighting'?'Contact our team for available models and project recommendations.':'Try clearing the filters or discuss your requirements with our team.')+'</p><a class="gold" href="/contact.html#quote">DISCUSS YOUR PROJECT →</a></div>';count.textContent=rows.length+' '+(rows.length===1?'Product':'Products');pager.innerHTML=rows.length?(page>1?'<button type="button" data-page="'+(page-1)+'">Previous</button>':'')+Array.from({length:pages},(_,i)=>'<button type="button" data-page="'+(i+1)+'"'+(page===i+1?' aria-current="page"':'')+'>'+(i+1)+'</button>').join('')+(page<pages?'<button type="button" data-page="'+(page+1)+'">Next →</button>':''):'';selection()}function clear(){checks.forEach(x=>x.checked=false);page=1;render()}checks.forEach(x=>x.addEventListener('change',()=>{page=1;render()}));sort.addEventListener('change',()=>{page=1;render()});document.querySelector('#directory-clear').addEventListener('click',clear);document.querySelector('.directory-filter-toggle').addEventListener('click',e=>{const open=document.querySelector('#directory-filters').classList.toggle('is-open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.querySelector('span').textContent=open?'−':'+'});document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{grid.classList.toggle('is-list',b.dataset.view==='list');document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));pageRoot.addEventListener('click',e=>{const add=e.target.closest('[data-add]'),next=e.target.closest('[data-page]');if(add){const id=add.dataset.add;if(!data.some(x=>x.id===id))return;selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];try{localStorage.setItem('elvaro-project',JSON.stringify(selected))}catch{}add.setAttribute('aria-pressed',String(selected.includes(id)));add.textContent=selected.includes(id)?'Added ✓':'Add to Project';selection()}if(next){page=Number(next.dataset.page);render();document.querySelector('.directory-toolbar').scrollIntoView({block:'start',behavior:'auto'})}});selection();fetch('/assets/product-directory-data.json').then(r=>{if(!r.ok)throw Error('Unavailable');return r.json()}).then(rows=>{if(!Array.isArray(rows))throw Error('Invalid catalogue');data=rows;const valid=new Set(data.map(x=>x.id));selected=selected.filter(x=>valid.has(x));try{localStorage.setItem('elvaro-project',JSON.stringify(selected))}catch{}const current=data.filter(x=>category==='all'||x.cat===category);checks.forEach(input=>{const key=input.dataset.filter;input.disabled=!current.some(x=>Array.isArray(x[key])?x[key].includes(input.value):x[key]===input.value);input.closest('label').style.opacity=input.disabled?'.4':'1'});render()}).catch(()=>{count.textContent='Browse available products';document.querySelector('.directory-toolbar').title='Refresh to load sorting and filters';checks.forEach(x=>x.disabled=true);sort.disabled=true;document.querySelectorAll('[data-add]').forEach(x=>{x.disabled=true;x.textContent='Contact us'})});})();
